exec('import yfinance as yf\nT=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]\nD=yf.download(T,period="3mo",progress=False,auto_adjust=True)\nC=D["Close"]; V=D["Volume"]; R=[]\nfor t in T:\n c=C[t].dropna(); v=V[t].reindex(c.index).dropna()\n if len(c)<22 or len(v)<22: continue\n p=float(c.iloc[-2]); var=(p/float(c.iloc[-7])-1)*100; mm=float(c.iloc[-21:-1].mean()); rvol=float(v.iloc[-2])/float(v.iloc[-22:-2].mean()); d=c.diff().iloc[-15:-1]; g=float(d.clip(lower=0).mean()); l=float((-d.clip(upper=0)).mean()); rsi=100 if l==0 else 100-(100/(1+g/l)); score=(35 if p>mm else -20)+(25 if 3<var<8 else 10 if 0<=var<=3 else -25 if var<=-3 else 0)+(20 if rvol>=1.5 else 10 if rvol>=1 else 0)+(20 if 50<=rsi<=65 else 10 if 45<=rsi<75 else -30); score=max(0,min(100,score)); signal="SURCHAUFFE" if var>=8 or rsi>=75 else "ACHAT" if p>mm and 3<var<8 and 50<=rsi<70 else "SURVEILLANCE" if p>mm and rsi>=40 else "AUCUN SIGNAL"; R.append((t,score,signal,var,rsi,rvol))\nR.sort(key=lambda x:x[1],reverse=True)\nprint("CLASSEMENT AJUSTE AU RISQUE")\nfor i,x in enumerate(R,1): print("{}. {} | Score {}/100 | {} | Var5j {:+.2f}% | RSI {:.1f} | RVOL {:.2f}".format(i,x[0],x[1],x[2],x[3],x[4],x[5]))')
